/* Product concept: fictional records, simulated workflows, no connected services. */
const oldAction=action,oldBind=bind,oldNavigate=navigate,oldDrawer=drawer,originalCoaching=coaching;
const channels=[{name:'Paid social',short:'SOC',color:'#8273e3',leads:160,spend:6000,placed:20,revenue:20000,kind:'Paid acquisition',note:'Social platforms, creative and landing pages',campaign:'Family protection conversations'},{name:'Paid search',short:'SEA',color:'#479cca',leads:80,spend:3000,placed:26,revenue:28000,kind:'High-intent search',note:'Keywords, intent and conversion paths',campaign:'Local life insurance inquiries'},{name:'Referral',short:'REF',color:'#39a18a',leads:80,spend:1000,placed:30,revenue:32000,kind:'Relationship growth',note:'Customers, partners and referrals',campaign:'Introductions from existing clients'},{name:'Organic search & local',short:'SEO',color:'#d7a442',leads:null,spend:null,kind:'Discovery',note:'SEO, local visibility and website inquiries'},{name:'Content & organic social',short:'ORG',color:'#dd8260',leads:null,spend:null,kind:'Education',note:'Articles, video and social content'},{name:'Email & SMS nurture',short:'MSG',color:'#787fc6',leads:null,spend:null,kind:'Follow-through',note:'Lifecycle sequences and reactivation'},{name:'Events & webinars',short:'EVT',color:'#a585c7',leads:null,spend:null,kind:'Community',note:'Registrations, attendance and follow-up'},{name:'Outbound & partnerships',short:'OUT',color:'#6396a8',leads:null,spend:null,kind:'Business development',note:'Approved outreach and partner introductions'},{name:'AI discovery & emerging channels',short:'AI',color:'#607fb4',leads:null,spend:null,kind:'Emerging discovery',note:'AI referrals and eligible emerging ad channels'},{name:'Other / custom sources',short:'ADD',color:'#8593a7',leads:null,spend:null,kind:'Configurable',note:'Purchased leads, direct mail and other sources'}];
const groupNav=[['OVERVIEW',[['dashboard','grid','Growth overview']]],['ATTRACT & CONVERT',[['marketing','chart','Marketing & channels'],['contacts','users','Contacts'],['opportunities','pipeline','Lead pipeline'],['conversations','chat','Conversations'],['calendar','calendar','Calendars']]],['DEVELOP PRODUCERS',[['producers','users','Activity & performance'],['coaching','book','Training & coaching'],['knowledge','book','Playbooks & answers'],['recruiting','users','Recruiting & onboarding']]],['COORDINATE & MEASURE',[['actions','tasks','Executive actions'],['coordination','pipeline','Cases & retention'],['profitability','money','Profitability & ROI']]],['THE PRODUCT',[['platform','grid','Platform & AMS fit']]]];
navs.splice(0,navs.length,...groupNav.flatMap(g=>g[1]));
const pageAllowed=p=>state.role==='owner'?true:state.role==='manager'?!['profitability','marketing','automation'].includes(p):state.role==='individual'?['dashboard','platform'].includes(p):!['marketing','automation','producers','recruiting','profitability'].includes(p);
const isOwn=()=>state.role==='owner';
render=function(){if(!pageAllowed(state.page))state.page='dashboard';document.getElementById('app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="mark">${ic('chart')}</div><div>Growth<span>& PERFORMANCE</span></div></div><button class="location" data-action="workspace"><span class="location-monogram">N</span><span>Northstar Insurance<small>Demo workspace · Austin, TX</small></span></button><div class="navscroll">${groupNav.map(([group,items])=>{let ns=items.filter(n=>pageAllowed(n[0]));return ns.length?`<div class="navlabel">${group}</div><nav class="nav">${ns.map(([p,i,n])=>`<button data-page="${p}" class="${state.page===p?'active':''}">${ic(i)}${n}</button>`).join('')}</nav>`:''}).join('')}</div><div class="sidebar-bottom"><strong>Growth + producer development</strong><span>Works alongside your AMS.</span><button class="textlink" style="color:#c0b7ff;margin-top:8px" data-page="platform">Understand the distinction →</button></div></aside><div class="main"><header class="topbar"><button class="ghost menu-toggle" aria-label="Toggle navigation" data-action="menu">${ic('menu')}</button><div class="breadcrumb"><strong>${navs.find(n=>n[0]===state.page)?.[2]}</strong><span class="top-divider"></span><span>Northstar Insurance</span></div><div class="top-right"><button class="small tour-button" data-action="tour">${ic('spark')} Explore the concept</button><select class="role" id="role" aria-label="Demo role">${[['owner','Agency owner'],['manager','Team manager'],['producer','Morgan · Producer'],['individual','Independent producer']].map(([k,n])=>`<option value="${k}" ${state.role===k?'selected':''}>${n}</option>`).join('')}</select><span class="avatar">${state.role==='owner'?'AC':state.role==='manager'?'JL':state.role==='individual'?'JT':'MR'}</span></div></header><div class="demo-strip"><span><b>CONCEPT DEMO</b><span class="strip-extra"> · Sample data & simulated actions</span></span><button data-action="reset">Reset walkthrough ↺</button></div><main class="content">${tourHTML()}${state.role==='individual'&&state.page==='dashboard'?individualHome():views[state.page]()}</main></div><button class="askbox" data-action="ask">${ic('spark')} ${state.role==='owner'?'Ask about performance':'Ask your assistant'}</button>`;bind();};
navigate=function(p){if(!views[p]||!pageAllowed(p))return;state.page=p;state.search='';closeDrawer();render();window.scrollTo({top:0,behavior:'instant'})};
views.dashboard=function(){if(state.role==='manager')return managerHome();if(state.role==='producer')return producerHome();if(state.role==='individual')return individualHome();return `<div class="command-head"><div><p class="eyebrow">NORTHSTAR INSURANCE / GROWTH & PRODUCER PERFORMANCE</p><h1>See the whole growth story.</h1><p>Your marketing. Your producers. Their next improvement.</p></div><button class="primary" data-action="brief">${ic('spark')} Open today’s brief</button></div><div class="growth-ribbon"><div><span>ACQUISITION</span><strong>320 <small>leads</small></strong><p>3 measured sources</p></div><b>→</b><div><span>PRODUCER EXECUTION</span><strong>76 <small>placements</small></strong><p>23.8% lead-to-placement</p></div><b>→</b><div><span>CONTINUOUS DEVELOPMENT</span><strong>6 <small>producer plans</small></strong><p>Individual focus, shared standards</p></div><b>→</b><div><span>${isOwn()?'FINANCIAL RESULT':'TEAM FOLLOW-THROUGH'}</span><strong>${isOwn()?'$20,000':'3'} <small>${isOwn()?'profit':'priorities'}</small></strong><p>${isOwn()?'After direct & shared costs':'Ready for a manager’s review'}</p></div></div><div class="workbench"><section class="growth-engine"><div class="section-heading"><span class="section-number">01</span><div><h2>The marketing engine</h2><p>Where opportunity starts</p></div><button class="ghost small" data-page="marketing" aria-label="Open marketing channels">${ic('arrow')}</button></div><div class="channel-stack">${channels.slice(0,3).map(c=>`<button data-channel="${c.name}" class="channel-line"><span class="channel-symbol" style="--channel:${c.color}">${c.short}</span><span><strong>${c.name}</strong><small>${c.campaign}</small></span><span class="channel-result">${c.leads}<small>leads</small></span></button>`).join('')}</div><div class="channel-pills"><span>Organic & local</span><span>Content</span><span>Email / SMS</span><span>Events</span><span>Outbound</span><span>Custom sources</span></div><button class="engine-link" data-page="marketing">Explore channels, campaigns & funnels ${ic('arrow')}</button><div class="engine-note"><span>FEEDBACK TO MARKETING</span><p>Conversations reveal customer expectations, lead fit and content gaps.</p><button class="textlink" data-feature="feedback">See a campaign insight →</button></div></section><section class="story-panel"><div class="section-heading"><span class="section-number">02</span><div><h2>The lead behind the numbers</h2><p>Follow one customer across the system</p></div><span class="badge">Interactive story</span></div><div class="story-person"><span class="avatar">RB</span><div><h2>Rachel Bennett</h2><p>Paid social → Morgan Reed → Next conversation</p></div><span class="badge orange">Follow-up to review</span></div><div class="journey-line">${[['Campaign','Family protection','campaign'],['Inquiry','Source captured','lead'],['Conversation','Partner involved','conversation'],['Follow-through',state.sent?'Demo send recorded':'Summary requested','followup']].map(([h,p,id],i)=>`<button data-journey="${id}" class="journey-node ${i===2?'selected':''}"><i>${i+1}</i><strong>${h}</strong><span>${p}</span></button>`).join('')}</div><blockquote>“I need to speak with my partner. Please email the summary and call me Thursday afternoon.”</blockquote><div class="story-consequence"><div>${ic('tasks')}<span><strong>One operating action</strong><p>Give the summary and callback a clear owner.</p></span></div><div>${ic('book')}<span><strong>One development opportunity</strong><p>Coach Morgan to agree a specific time.</p></span></div></div><button class="primary" data-action="morgan-conversation">Open the conversation & next steps ${ic('arrow')}</button></section></div><div class="development-band"><div><p class="eyebrow">03 / DEVELOP THE PRODUCER</p><h2>Every conversation can improve the next one.</h2></div><div class="learning-loop">${[['Learn','lesson'],['Practise','practice'],['Apply','morgan-conversation'],['Review','coach-review']].map(([n,a],i)=>`<button data-action="${a}"><span>${i+1}</span>${n}${i<3?ic('arrow'):''}</button>`).join('')}</div><button class="textlink" data-page="coaching">Open training & coaching →</button></div><div class="overview-bottom"><button data-page="producers"><span>PRODUCER ACTIVITY</span><strong>Who needs help, and with what?</strong><p>Response, conversations, commitments and conversion.</p>${ic('arrow')}</button><button data-page="coordination"><span>CUSTOMER CONTINUITY</span><strong>Keep the next handoff moving.</strong><p>Applications, service, persistency and referrals.</p>${ic('arrow')}</button><button data-page="${isOwn()?'profitability':'actions'}"><span>${isOwn()?'ECONOMICS':'EXECUTION'}</span><strong>${isOwn()?'See the return after the costs.':'See the work needing attention.'}</strong><p>${isOwn()?'Source return, producer contribution and agency profit.':'Evidence, ownership and verified follow-through.'}</p>${ic('arrow')}</button></div><div class="ams-bottom"><span>${ic('info')} <strong>A growth and producer-performance platform. Not an AMS replacement.</strong></span><button class="textlink" data-page="platform">See how the systems fit together →</button></div><p class="footnote">Financial and conversion examples: August 2026 · Operational scenario: September 21, 2026 · Fictional data throughout.</p>`};
function sectionTabs(items,selected,attr){return `<div class="tabs">${items.map(([k,v])=>`<button data-${attr}="${k}" class="${selected===k?'active':''}">${v}</button>`).join('')}</div>`}
views.marketing=function(){const t=state.marketingTab||'channels';return header('Marketing & lead generation','Connect every acquisition activity to what happens after the inquiry.',`<button class="primary" data-feature="campaign-builder">${ic('spark')} Explore a campaign</button>`)+sectionTabs([['channels','Channels'],['campaigns','Campaigns'],['funnels','Funnels & nurture'],['feedback','Conversation feedback']],t,'marketingtab')+(t==='channels'?`<div class="marketing-intro"><div><p class="eyebrow">THE COMPLETE ACQUISITION PICTURE</p><h2>More than a lead count.</h2><p>Follow source → campaign → customer → producer → outcome.<br>Keep assisted touches visible without counting the same lead twice.</p></div><div><strong>320</strong><span>unique sample leads</span></div><div><strong>$10,000</strong><span>measured acquisition spend</span></div></div><div class="channel-grid">${channels.map(c=>`<button class="channel-card" data-channel="${c.name}"><div class="channel-card-top"><span class="channel-symbol" style="--channel:${c.color}">${c.short}</span><span class="badge ${c.leads!==null?'green':''}">${c.leads!==null?'Illustrative results':'Concept channel'}</span></div><h2>${c.name}</h2><p>${c.note}</p><div class="channel-stats">${c.leads!==null?`<span><strong>${c.leads}</strong>Leads</span><span><strong>${c.placed}</strong>Placed</span><span><strong>${money(c.spend)}</strong>Spend</span>`:`<span class="muted">Workflow preview · No measured results</span>`}</div><div class="channel-card-footer">${c.leads!==null?'Inspect source and campaign':'Explore channel workflow'} ${ic('arrow')}</div></button>`).join('')}</div><p class="footnote">Source totals reconcile to 320 leads, 76 placements and $10,000 spend. Additional channels demonstrate intended scope; unmeasured is not zero.</p>`:t==='campaigns'?`<div class="campaign-layout"><div class="campaign-feature"><p class="eyebrow">PAID SOCIAL / SAMPLE CAMPAIGN</p><h1>Family protection<br>conversations.</h1><p>A useful first conversation, followed by a producer who has the context.</p><div class="campaign-tags"><span>Education-led</span><span>Appointment inquiry</span><span>Human review</span></div><button data-feature="campaign-builder">Open campaign workspace ${ic('arrow')}</button></div><div class="card"><div class="cardhead"><h2>Campaign → producer → result</h2></div><div class="campaign-flow">${[['160','Inquiries captured','Original campaign and contact preference recorded'],['Morgan + team','Assigned producers','Routing follows the approved team rules'],['20','Placed policies','Confirmed outcome in this fictional closed-month example'],['$5,000','Source contribution','After $6,000 spend and $9,000 compensation/service']].map(([v,k,d])=>`<div><strong>${v}</strong><span><b>${k}</b><small>${d}</small></span></div>`).join('')}</div><div class="cardfooter"><button class="textlink" data-action="morgan-conversation">Inspect Rachel’s journey →</button><button class="textlink" data-page="profitability">Check the economics →</button></div></div></div><div class="card" style="margin-top:22px"><div class="cardhead"><h2>Campaign workbench</h2><span class="badge">Planning and review example</span></div><div class="task"><span class="badge">Draft</span><div><h3>Creative and messaging</h3><p>Clarify what the first appointment covers. Agency review required before publishing.</p></div><button class="small taskaction" data-feature="creative">Review draft</button></div><div class="task"><span class="badge orange">Review</span><div><h3>Lead fit and customer expectations</h3><p>Use conversation evidence to improve the campaign brief.</p></div><button class="small taskaction" data-feature="feedback">See evidence</button></div></div>`:t==='funnels'?`<div class="funnel-workspace"><div class="funnel-steps">${[['01','Capture','Campaign-specific landing page and form'],['02','Route','Assign a producer and carry the source'],['03','Book','Offer a suitable time and record preferences'],['04','Nurture','Approved reminders, pause on reply'],['05','Verify','Check the next action and confirmed outcome']].map(([n,h,p])=>`<button data-funnel="${h}"><span>${n}</span><div><strong>${h}</strong><p>${p}</p></div>${ic('arrow')}</button>`).join('')}</div><div class="landing-preview"><div class="preview-browser"><i></i><i></i><i></i><span>northstar.example / conversation</span></div><div class="landing-body"><div class="landing-brand">NORTHSTAR INSURANCE</div><h1>Start with a<br>conversation.</h1><p>Tell us what you want to understand. A producer will help you explore the next step.</p><label>Name<input placeholder="Rachel Bennett" disabled></label><label>Preferred contact method<select disabled><option>Email, then a scheduled call</option></select></label><button class="primary wide" data-feature="simulate-lead">Simulate an inquiry ${ic('arrow')}</button><span class="footnote">Concept form. No submission or external contact.</span></div></div></div><div class="ai-panel"><h3>${ic('spark')} Workflow review</h3><p>Every sequence needs an approved purpose, contact preferences, clear ownership, and a stop condition. An inbound reply pauses the sample nurture path and returns the conversation to a producer.</p><button data-feature="automation">Inspect the workflow →</button></div>`:`<div class="feedback-feature"><span class="badge">CONVERSATIONS → MARKETING</span><h1>The campaign gets smarter<br>when it hears the customer.</h1><p>Customer language informs the next creative brief, landing-page explanation and producer preparation.</p></div><div class="twocol"><div class="card lesson"><span class="lesson-num">SOURCE / RACHEL’S CONVERSATION</span><blockquote>“I need to speak with my partner.”</blockquote><p>One example suggests that another decision-maker may need to join the conversation. It does not establish a market-wide pattern.</p><button data-page="conversations">Read the source →</button></div><div class="card lesson"><span class="lesson-num">PROPOSED RESPONSE / NEEDS REVIEW</span><h2>Make space for a shared decision.</h2><p>Test whether appointment messaging should invite customers to include a partner. Prepare producers to confirm attendees and the next step.</p><button class="primary" data-feature="creative">Review the proposed message →</button></div></div><p class="footnote">Campaign claims, channel eligibility and launch settings require separate review. This is not a live campaign or a promise of improved results.</p>`)};
views.producers=function(){return header('Producer activity & performance','Understand the work, diagnose the gap, and connect it to development.',`<button data-page="coaching">Open team development ${ic('arrow')}</button>`)+`<div class="performance-mast"><div><p class="eyebrow">THE QUESTION BEHIND THE SCOREBOARD</p><h1>Is it lead quality, execution,<br>or a skill that needs support?</h1><p>Measure the activity. Inspect a conversation. Choose the next improvement.</p></div><div class="focus-producer">${avatar(people[1])}<div><strong>Morgan Reed</strong><span>Current focus: specific follow-through</span></div><button class="primary small" data-action="morgan-conversation">Review evidence</button></div></div><div class="card"><div class="cardhead"><h2>From activity to outcome</h2><span class="badge">August 2026 · Sample activity</span></div><div class="table-wrap"><table><thead><tr><th>Producer</th><th>Leads</th><th>Conversations</th><th>Appointments held</th><th>Placed</th><th>Conversion</th><th>Development focus</th></tr></thead><tbody>${people.map((p,i)=>`<tr><td><button class="tablebtn namecell" data-performance="${p.name}">${avatar(p)}<strong>${p.name}</strong></button></td><td>${p.leads}</td><td>${[48,48,45,36,32,24][i]}</td><td>${[30,24,26,20,18,14][i]}</td><td>${p.placed}</td><td>${(p.placed/p.leads*100).toFixed(1)}%</td><td><button class="textlink" data-producer-training="${p.name}">${['Peer coaching','Specific next steps','Callback verification','Customer preparation','Handoff clarity','Core foundations'][i]} →</button></td></tr>`).join('')}</tbody></table></div></div><div class="twocol" style="margin-top:22px"><div class="card lesson"><span class="badge orange">MORGAN / REVIEW NEEDED</span><h2>A commitment without a confirmed time.</h2><p>Rachel’s call contains a clear request and an incomplete next-step agreement. Review the source before deciding whether coaching, a process fix, or both are needed.</p><button class="primary" data-action="morgan-conversation">Open the source conversation →</button></div><div class="card lesson"><span class="badge">MANAGER’S VIEW</span><h2>Activity is not the whole result.</h2><p>Conversation counts do not prove quality. Compare lead fit, follow-through, customer outcomes and later evidence before assessing performance.</p><button data-action="coach-review">Open the review criteria →</button></div></div>`};
function marketingChannel(name){if(state.role!=='owner')return;const c=channels.find(c=>c.name===name);if(!c)return;drawer(c.name,`<span class="badge">${c.kind}</span><p>${c.note}.</p>${c.leads!==null?`<div class="inset"><strong>${c.leads} leads · ${c.placed} placements</strong><br>${money(c.spend)} acquisition spend · ${money(c.revenue)} net commission revenue</div>`:'<div class="inset">Channel concept only. No measured results, spend or active connection.</div>'}<h3>What the platform connects</h3><div class="stack">${['Campaign purpose and approved message','Landing page, form or other capture point','Source, contact preferences and assigned producer','Conversations, follow-up and confirmed outcomes','Attributable cost and return where data supports it'].map((t,i)=>`<div class="detailrow"><span>${i+1}. ${t}</span></div>`).join('')}</div><button class="primary wide" style="margin-top:22px" data-feature="campaign-builder">Explore the campaign workflow</button><p class="footnote">Concept scope does not establish a native connector or channel eligibility.</p>`,'MARKETING & LEAD GENERATION')}
views.coaching=function(){let t=state.trainingTab||'development';return header('Training & ongoing development','Build the foundation. Coach the real work. Review whether behavior changes.',`<button class="primary" data-action="practice">${ic('book')} Try a practice scenario</button>`)+sectionTabs([['development','Development cycle'],['paths','Training paths'],['onboarding','New producer onboarding'],['reviews','Manager reviews']],t,'trainingtab')+(t==='development'?`<div class="development-hero"><div><span class="badge">MORGAN REED / PERSONAL DEVELOPMENT PLAN</span><h1>Better next steps.<br>Better follow-through.</h1><p>The coaching focus comes from a specific customer conversation, then follows the producer back into daily work.</p><button class="primary" data-action="practice">Start the practice ${ic('arrow')}</button></div><div class="development-track">${[['01','Evidence','Rachel asks for Thursday afternoon.','morgan-conversation'],['02','Learn','Confirm the action, time and attendees.','lesson'],['03','Practise',state.practice?'Exercise completed; application still unverified.':'Rehearse the exact customer situation.','practice'],['04','Apply & review','Check a later conversation for changed behavior.','coach-review']].map(([n,h,d,a])=>`<button data-action="${a}"><i>${n}</i><span><strong>${h}</strong><small>${d}</small></span>${ic('chevron')}</button>`).join('')}</div></div><div class="twocol" style="margin-top:22px"><div class="card lesson"><span class="lesson-num">BEFORE THE CONVERSATION</span><h2>Prepare with the right context.</h2><p>Bring the customer’s source, history, stated preferences and approved agency guidance into the producer’s preparation.</p><button data-feature="prep">Open Rachel’s preparation brief →</button></div><div class="card lesson"><span class="lesson-num">AFTER THE CONVERSATION</span><h2>Convert promises into owned work.</h2><p>Review the summary, approve the next step and verify completion. The manager sees the exception if work remains unresolved.</p><button data-page="conversations">Review the suggested follow-up →</button></div></div>`:t==='paths'?`<div class="training-grid">${[['Foundations','For new producers','Agency process, customer care, source records and approved playbooks',4,6],['Conversations & discovery','Applied to real calls','Understand the request, clarify context and confirm a useful next step',2,5],['Follow-through & handoffs','Morgan’s current focus','Turn commitments into actions and hand the customer forward with context',1,4],['Ongoing service & referrals','After placement','Coordinate service, reviews and appropriate referral requests',0,4]].map(([h,k,d,n,total],i)=>`<div class="card lesson"><span class="lesson-num">${k.toUpperCase()}</span><h2>${h}</h2><p>${d}.</p><div class="bar"><i style="width:${n/total*100}%"></i></div><span class="footnote">${n} of ${total} sample lessons complete</span><button data-track="${i}">Open learning path →</button></div>`).join('')}</div><p class="footnote">These are agency process and coaching examples, not accredited continuing education or licensing training.</p>`:t==='onboarding'?`<div class="onboarding-header"><div><p class="eyebrow">NEW PRODUCER / SAMPLE PLAN</p><h1>A clear path to readiness.</h1><p>Training completion supports a manager’s decision. It does not authorize insurance activity.</p></div><span class="badge orange">Manager sign-off required</span></div><div class="card">${[['1','Agency orientation','Team, responsibilities and escalation routes','Complete'],['2','Systems and approved sources','CRM, records, customer preferences and playbooks','Complete'],['3','Conversation practice','Preparation, listening and a specific next step','In progress'],['4','Observed application','Manager reviews sample or permitted real conversations','Awaiting evidence'],['5','Readiness review','Authorized leader confirms required readiness and permissions','Not yet approved']].map(([n,h,d,status])=>`<div class="task"><span class="section-number">${n}</span><div><h3>${h}</h3><p>${d}</p></div><button class="small taskaction" data-onboard="${n}">${status} ${ic('chevron')}</button></div>`).join('')}</div>`:`<div class="card"><div class="cardhead"><h2>Evidence of development</h2><span class="badge">Human review</span></div><div class="table-wrap"><table><thead><tr><th>Producer</th><th>Agreed focus</th><th>Learning</th><th>Application evidence</th><th>Review</th></tr></thead><tbody>${(state.role==='producer'?[people[1]]:people.slice(0,3)).map(p=>`<tr><td>${p.name}</td><td>${p.name==='Morgan Reed'?'Specific next steps':'Approved agency standards'}</td><td>${p.name==='Morgan Reed'&&state.practice?'Practice completed':'In progress'}</td><td><span class="badge orange">${p.name==='Morgan Reed'?(state.development?.reviewDecision||'Sample ready to review'):'Later call needed'}</span></td><td>${p.name==='Morgan Reed'?'<button class="textlink" data-action="coach-review">Review sample →</button>':'<span class="muted">No later-call sample</span>'}</td></tr>`).join('')}</tbody></table></div></div><div class="ai-panel"><h3>${ic('info')} Separate skill gaps from process constraints.</h3><p>Missing data, unclear routing or poor-fit inquiries can affect results. A manager reviews the supporting record before attributing a result to the producer.</p></div>`)};
views.knowledge=function(){return header('Playbooks & approved answers','Give producers a source they can trust—and an escalation when it is missing.')+`<div class="knowledge-layout"><div class="knowledge-ask"><p class="eyebrow">AT THE POINT OF WORK</p><h1>What should<br>I do next?</h1><p>Answers should cite approved agency guidance, show its date, and stop where the source runs out.</p><div class="stack"><button data-knowledge="followup">How do I record a promised callback?</button><button data-knowledge="handoff">What belongs in an application handoff?</button><button data-knowledge="coverage">Which coverage should this customer choose?</button></div><div id="knowledge-answer" aria-live="polite"></div></div><div class="stack">${[['Follow-through playbook','Version 2.1 · Sample approval: Sep 1, 2026','Owners, time commitments, preferred channels and verification.','followup'],['Application handoff checklist','Version 1.3 · Sample approval: Aug 28, 2026','Customer context, agreed next step, required information and responsible owner.','handoff'],['Escalation guide','Version 1.0 · Sample approval: Sep 1, 2026','Route advice, ambiguous guidance and consequential decisions to authorized people.','coverage']].map(([h,v,d,k])=>`<button class="knowledge-doc" data-knowledge="${k}">${ic('book')}<span><strong>${h}</strong><small>${v}</small><p>${d}</p></span>${ic('chevron')}</button>`).join('')}<div class="inset"><strong>Learning improves the playbook.</strong><br>Repeated unanswered questions can reveal documentation gaps. The agency approves changes before reuse.</div></div></div>`};
views.recruiting=function(){return header('Recruiting & producer onboarding','Coordinate the people pipeline, then support readiness.',`<button data-feature="recruiting-fit">${ic('info')} Human decisions</button>`)+`<div class="people-pipeline">${[['Candidate conversations',[['Jordan Taylor','Interview scheduled · Sep 23'],['Casey Moore','Availability requested']]],['Onboarding preparation',[['Avery Lewis','Orientation checklist in progress']]],['Learning & practice',[['Noah Davis','Core foundations · Manager review pending']]]].map(([h,items])=>`<div class="lane"><div class="lanehead">${h}<span class="badge">${items.length}</span></div>${items.map(([n,d])=>`<div class="opportunity"><h3>${n}</h3><p>${d}</p><button class="small wide" data-recruit="${n}">Open coordination record →</button></div>`).join('')}</div>`).join('')}</div><div class="ai-panel"><h3>${ic('users')} Selection and readiness stay with agency leaders.</h3><p>The concept organizes candidates, interviews, access setup and learning tasks. It does not select candidates, infer suitability or grant licensing or selling authority.</p><button class="primary small" data-feature="producer-onboarding">Explore the producer onboarding path →</button></div>`};
views.coordination=function(){const t=state.careTab||'handoffs';return header('Cases, service & retention','Keep the customer moving without replacing the insurance record.',`<span class="badge">Coordination alongside the AMS / carrier</span>`)+sectionTabs([['handoffs','Case handoffs'],['journey','Customer journey'],['care','Service & persistency']],t,'caretab')+(t==='handoffs'?`<div class="coordination-banner"><strong>Coordinate the next action here.</strong><span>Verify policy and case status in the authorized source system.</span></div><div class="card"><div class="cardhead"><h2>Dependencies that need an owner</h2></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Dependency</th><th>Responsible person</th><th>Source status</th><th>Next action</th></tr></thead><tbody>${[['Daniel Foster','Customer information outstanding','Lena Brooks','Sample carrier record · Sep 21','Prepare reminder'],['Ava Mitchell','Application handoff needs review','Alex Carter','Sample CRM handoff · Sep 20','Review checklist'],['Rachel Bennett','Summary and call-time confirmation','Morgan Reed','Sample conversation · Sep 18','Open conversation']].filter(r=>state.role!=='producer'||r[2]==='Morgan Reed').map((r,i)=>`<tr>${r.slice(0,4).map(x=>`<td>${x}</td>`).join('')}<td><button class="textlink" data-case="${r[0]}">${r[4]} →</button></td></tr>`).join('')}</tbody></table></div></div><div class="twocol" style="margin-top:22px"><div class="card lesson"><h2>A complete handoff</h2><p>Preserve customer context, source, producer commitments, missing information and the owner of the next step.</p><button data-case="Ava Mitchell">Inspect a sample handoff →</button></div><div class="card lesson"><h2>Visible verification</h2><p>A task status does not establish a policy status. Show the source, its timestamp and anything that remains uncertain.</p><button data-feature="status-source">Inspect the source boundary →</button></div></div>`:t==='journey'?`<div class="customer-journey">${[['01','Interest','Marketing captures an inquiry with source and preferences.','marketing','Growth + systems'],['02','Connection','A producer owns the relationship and the next conversation.','contacts','Agency team + producer'],['03','Advice','An authorized professional understands needs and guides decisions.','conversations','Licensed team'],['04','Application','The team coordinates requirements and missing information.','coordination','Team + source systems'],['05','Placement','Authorized records establish delivery, acceptance and status.','coordination','Licensed team + carrier'],['06','Ongoing care','Service, reviews, retention and referrals remain visible.','coordination','Agency team']].map(([n,h,d,p,owner])=>`<button data-journey-stage="${n}" class="journey-stage"><span>${n}</span><h2>${h}</h2><p>${d}</p><strong>${owner}</strong></button>`).join('')}</div><div class="inset">At every stage: a responsible person, a clear next action and enough context for the next person to continue.</div>`:`<div class="twocol"><div class="card"><div class="cardhead"><h2>Ongoing customer care</h2></div>${[['Emma Collins','Service question awaiting a response','Sofia Chen'],['William Hayes','Annual review preparation','Lena Brooks'],['Rachel Bennett','Preferred follow-up time to confirm','Morgan Reed']].filter(r=>state.role!=='producer'||r[2]==='Morgan Reed').map(([n,d,p])=>`<div class="task"><span class="brief-icon teal">${ic('users')}</span><div><h3>${n}</h3><p>${d}<br>${p}</p></div><button class="small taskaction" data-service="${n}">Review</button></div>`).join('')}</div><div class="card lesson"><span class="badge">PERSISTENCY / DATA REQUIREMENT</span><h2>Keep policy status anchored to its source.</h2><p>A real persistency measure needs policy inception, in-force and lapse information over a defined period. This demo has no connected policy cohort, so it does not invent a retention percentage.</p><button data-feature="persistency">Explore the intended view →</button></div></div><div class="development-band"><div><p class="eyebrow">THE NEXT GROWTH OPPORTUNITY</p><h2>Reviews and referrals, with context.</h2></div><p style="font-size:13px;flex:1;color:#628879">After a service need is resolved, an approved workflow can prepare a relevant review or referral invitation for human review.</p><button data-feature="referral">Preview the invitation</button></div>`)};
const coverage=[['1–3','Connected product concept','dashboard'],['4, 28–29, 35–36','Development partnership','platform'],['5–7','Channels, campaigns, CRM and nurture','marketing'],['8–9','Agentic coordination and executive brief','actions'],['10–12','Cases, customer journey and retention','coordination'],['13','Recruiting, onboarding and approved knowledge','recruiting'],['14','Operational value and accountability','actions'],['15–18','Conversations and follow-through','conversations'],['19–20','Training, practice and ongoing development','coaching'],['21','Marketing feedback from conversations','marketing'],['22','Producer preparation and daily support','coaching'],['23–26','Financials, source ROI and producer contribution','profitability'],['27','Control, evidence and insurance judgment','platform'],['30–32','Standard SaaS rollout and repeatability','platform'],['33–34','Editions, roles and information boundaries','platform']];
views.platform=function(){let t=state.platformTab||'fit';return header('The platform & the AMS','A clear role in the agency’s existing technology.',`<span class="badge">Working descriptor · Brand not selected</span>`)+sectionTabs([['fit','What this is'],['editions','Editions & roles'],['rollout','Standard rollout'],['partner','Development partnership'],['coverage','Full concept map']],t,'platformtab')+(t==='fit'?`<div class="positioning-panel"><p class="eyebrow">PROPOSED CATEGORY</p><h1>Insurance agency growth<br>& producer performance.</h1><p>Connect the acquisition of opportunity, the work of the producer, continuous development and the financial result.</p><strong>This is not an agency management system or a replacement for one.</strong></div><div class="system-fit"><div><span class="badge">GROWTH & FOLLOW-THROUGH</span><h2>Capture & coordinate</h2><p>Campaigns, funnels, CRM, communications, appointments and approved automation.</p><span class="footnote">A coordinated customer journey, with clear ownership and next steps.</span></div><div class="fit-core"><span class="badge">THE PROPOSED PRODUCT</span><h2>Improve growth & producer performance</h2><p>Link channel results to producer execution, conversation evidence, ongoing training and contribution after costs.</p><span class="footnote">These connected workflows are the proposition to test with agency owners.</span></div><div><span class="badge">AMS / CARRIER / ACCOUNTING</span><h2>Maintain authoritative records</h2><p>Policy administration, carrier records, insurance transactions and financial ledgers remain in the appropriate source system.</p><span class="footnote">Supported imports and integrations must be verified for each product.</span></div></div><div class="inset"><strong>There is real overlap.</strong><br>Modern AMS products may already offer CRM, marketing, reporting and AI. The case for an additional platform must be a useful, connected workflow and measurable value—not a claim that those features are missing everywhere.</div><div class="source-links">Research references: <a href="https://www1.appliedsystems.com/en-us/solutions/for-agents/agency-management-system/applied-epic" target="_blank" rel="noopener">Applied Epic</a><a href="https://www.vertafore.com/products/agency-management-software/ams360" target="_blank" rel="noopener">AMS360</a></div>`:t==='editions'?`<div class="twocol"><div class="card lesson"><span class="lesson-num">AGENCY EDITION</span><h2>One team. Appropriate visibility.</h2><p>Marketing and execution, team development and owner-authorized financial intelligence in a shared agency workspace.</p><button data-preview-role="owner">Preview agency owner</button><button data-preview-role="manager">Preview team manager</button><button data-preview-role="producer">Preview agency producer</button></div><div class="card lesson"><span class="lesson-num">INDIVIDUAL EDITION</span><h2>A producer’s own business.</h2><p>A separate workspace for an independent producer: personal CRM, follow-up, coaching and business performance from that subscriber’s own records.</p><button class="primary" data-preview-role="individual">Preview independent workspace</button><p class="footnote">A personal subscription does not unlock any agency’s information.</p></div></div><div class="card" style="margin-top:22px"><div class="cardhead"><h2>Information boundaries across the product</h2></div><div class="table-wrap"><table><thead><tr><th>Role</th><th>Activity & coaching</th><th>Agency financials</th><th>Records & answers</th></tr></thead><tbody><tr><td>Agency owner</td><td>Full agency</td><td>Owner-authorized access</td><td>Within agency permissions</td></tr><tr><td>Team manager</td><td>Assigned team</td><td>Only if explicitly granted</td><td>Assigned scope</td></tr><tr><td>Agency producer</td><td>Own records</td><td>No access</td><td>Own permitted scope</td></tr><tr><td>Individual subscriber</td><td>Own business</td><td>No agency access</td><td>Separate personal records</td></tr></tbody></table></div><div class="cardfooter">Production enforcement must cover dashboards, reports, exports and AI answers. Role previews are illustrative, not authentication.</div></div>`:t==='rollout'?`<div class="onboarding-header"><div><p class="eyebrow">ONE SHARED PRODUCT / SEPARATE CUSTOMER WORKSPACES</p><h1>Configure the agency.<br>Keep the product consistent.</h1><p>The partner agency should use the same onboarding path as the next customer.</p></div></div><div class="rollout-steps">${[['1','Agency profile','Identity, supported workflow profile and settings'],['2','Supported connections','Choose the agency records to connect and confirm access'],['3','People & roles','Invite the team and confirm permissions'],['4','Approved knowledge','Import agency playbooks into a common structure'],['5','Financial definitions','Confirm compensation, source attribution and costs'],['6','Readiness checks','Verify data, permission boundaries and approvals']].map(([n,h,d])=>`<button data-rollout="${n}"><span class="section-number">${n}</span><h3>${h}</h3><p>${d}</p>${ic('arrow')}</button>`).join('')}</div><div class="inset"><strong>Repeatability is a development goal.</strong><br>A second comparable agency should adopt existing workflows without a separate build. Measure onboarding effort, data completeness, usage cost, support needs and update reliability. Those results have not yet been established.</div>`:t==='partner'?`<div class="positioning-panel"><p class="eyebrow">DEVELOPED WITH AN AGENCY / DESIGNED FOR REPEATABLE ADOPTION</p><h1>Prove the product<br>in real agency work.</h1><p>The partnership combines technology and growth systems with insurance leadership and day-to-day operating experience.</p></div><div class="twocol"><div class="card lesson"><span class="lesson-num">ANDREW / PRODUCT & GROWTH</span><h2>Build the supporting systems.</h2><p>Marketing infrastructure, shared software, integrations, workflows, dashboards and product development.</p></div><div class="card lesson"><span class="lesson-num">AGENCY PARTNER / INSURANCE & PEOPLE</span><h2>Shape and validate the work.</h2><p>Agency workflows, insurance expertise, licensed execution, carrier relationships, approved training and producer leadership.</p></div></div><div class="inset"><strong>The conversation to have:</strong><br>Where would this matter most? What is already handled well by your current stack? What team access and time could each side contribute? How should responsibilities, product IP and customer data be handled?<br><br>Ownership, funding and commercial participation remain open. The demo is an invitation to explore—not evidence of an agreed partnership.</div>`:`<div class="card"><div class="cardhead"><div><h2>All 40 pages, connected to the experience</h2><p>The master concept’s capabilities and partnership story are represented here.</p></div></div><div class="table-wrap"><table><thead><tr><th>PDF pages</th><th>Concept</th><th>Explore</th></tr></thead><tbody>${coverage.map(([pages,h,p],i)=>`<tr><td>${pages}</td><td>${h}</td><td><button class="textlink" data-coverage="${i}">Open concept →</button></td></tr>`).join('')}</tbody></table></div></div><p class="footnote">The PDF’s earlier “operating system” label is superseded here by Andrew’s clarification: growth and producer performance, explicitly distinguished from an AMS.</p>`)};
function individualHome(){return `<div class="command-head"><div><p class="eyebrow">JORDAN TAYLOR / SEPARATE PERSONAL WORKSPACE</p><h1>Grow your own practice.</h1><p>Your pipeline, follow-through, development and business results.</p></div><span class="badge">Individual edition concept</span></div><div class="growth-ribbon"><div><span>YOUR INQUIRIES</span><strong>24</strong><p>Personal sample dataset</p></div><div><span>YOUR PLACEMENTS</span><strong>6</strong><p>August 2026</p></div><div><span>YOUR NET REVENUE</span><strong>$7,200</strong><p>After sample chargebacks</p></div><div><span>YOUR DIRECT COSTS</span><strong>$1,400</strong><p>Marketing & software</p></div></div><div class="twocol"><div class="card lesson"><span class="lesson-num">PERSONAL ACTIVITY</span><h2>Prepare the next conversation.</h2><p>Sample prospect: Jamie Ellis requested a follow-up after reviewing the information with a partner.</p><button data-feature="individual-record">Open personal sample record →</button></div><div class="card lesson"><span class="lesson-num">PERSONAL DEVELOPMENT</span><h2>Make the next step specific.</h2><p>Shared training capabilities can support an individual producer, using that subscriber’s own records and approved content.</p><button data-feature="individual-training">Explore the learning plan →</button></div></div><div class="inset">This is a separate fictional individual workspace. Its figures do not come from Northstar Insurance. Broader individual-edition workflows are represented as concept previews.</div><button data-feature="editions">Compare the two editions →</button>`}
function managerHome(){return header('Your team, ready for the next step.','Assigned team activity, coaching and operational exceptions.',`<span class="badge">Manager · Financial access not granted</span>`)+`<div class="twocol"><div class="card lesson"><span class="lesson-num">TODAY’S PRIORITY</span><h2>Rachel is waiting on a clear next step.</h2><p>Review Morgan’s promise, verify the activity and assign the follow-up plan.</p><button class="primary" data-action="morgan-conversation">Review the conversation →</button></div><div class="card lesson"><span class="lesson-num">TEAM DEVELOPMENT</span><h2>One focus for Morgan this week.</h2><p>Agree a specific time, channel and attendees. Practise, apply, then review a later call.</p><button data-page="coaching">Open training & coaching →</button></div></div><div class="card" style="margin-top:22px"><div class="cardhead"><h2>Open team commitments</h2></div>${taskRows(false)}</div><div class="actions" style="margin-top:22px"><button data-page="producers">Activity & performance</button><button data-page="coordination">Cases & retention</button></div>`};
const originalActionsView=views.actions;
views.actions=function(){return `<div class="agent-cycle">${[['Observe','Read permitted conversations, tasks and activity.'],['Interpret','Identify commitments, gaps and uncertainty.'],['Coordinate','Prepare the next action and request approval.'],['Verify','Check the result and surface unresolved work.']].map(([h,d])=>`<button data-agentstage="${h}"><strong>${h}</strong><span>${d}</span></button>`).join('')}</div>`+originalActionsView()};
function trainingPath(i){const paths=[['Core foundations',['Agency roles and escalation','Customer preferences and recordkeeping','Approved sources and playbooks','CRM and pipeline practice','Conversation rehearsal','Manager readiness review']],['Conversations & discovery',['Prepare with context','Listen for the actual request','Confirm decision participants','Agree a specific next step','Review a later conversation']],['Follow-through & handoffs',['Capture the commitment','Draft the requested next step','Assign and verify the work','Preserve context at handoff']],['Ongoing service & referrals',['Understand the service request','Confirm the authorized source','Close the loop with the customer','Review appropriate referral timing']]];const [title,lessons]=paths[Number(i)];drawer(title,`<span class="badge">Illustrative learning path</span><p>Each lesson combines approved guidance, a practice exercise and a reviewed application.</p><div class="stack">${lessons.map((l,n)=>`<button data-action="${n===lessons.length-1?'coach-review':'lesson'}" style="text-align:left;justify-content:flex-start"><span class="section-number">${n+1}</span>${l}</button>`).join('')}</div><p class="footnote">Sample curriculum only. The agency’s authorized leaders approve training and readiness.</p>`,'TRAINING PATH')}
function feature(f){switch(f){case 'feedback':state.marketingTab='feedback';navigate('marketing');break;case 'producer-onboarding':state.trainingTab='onboarding';navigate('coaching');break;case 'editions':state.platformTab='editions';navigate('platform');break;case 'campaign-builder':drawer('A connected campaign workspace',`<span class="badge">Paid social · Fictional concept</span><label class="modal-label">Campaign name</label><input class="wide" id="campaign-name" value="${esc(state.campaignName||'Family protection conversations')}"><div class="inset"><strong>Channel planning</strong><br>Map the agency’s chosen platforms, including social, search, video, AI discovery, email, referrals and offline sources. Availability and permissions require validation.<br><br><strong>Purpose</strong><br>Invite a first conversation about family protection needs.<br><br><strong>Journey</strong><br>Creative → Landing page → Inquiry → Producer → Conversation → Reviewed follow-up → Confirmed outcome</div><div class="detailrow"><span>Message review</span><span class="badge orange">Agency approval needed</span></div><div class="detailrow"><span>Responsible producer</span><strong>Morgan + team routing</strong></div><div class="detailrow"><span>Current launch status</span><strong>Not published / not connected</strong></div><div class="stack" style="margin-top:20px"><button class="primary" data-feature="save-campaign">Save demo campaign name</button><button data-feature="creative">Review message concept →</button><button data-feature="funnel-view">Inspect the capture and nurture path →</button></div><p class="footnote">No ad account, channel policy eligibility or delivery has been verified.</p>`,'MARKETING WORKBENCH');break;case 'save-campaign':state.campaignName=document.getElementById('campaign-name').value;toast('Campaign label saved in this demo session. Nothing published.');break;case 'creative':drawer('Creative and message review',`<span class="badge orange">Draft concept · Not an approved insurance ad</span><div class="inset"><strong>Proposed opening</strong><br>“Planning a conversation about family protection? Bring your questions—and include the people involved in the decision.”</div><h3>Why this is proposed</h3><p>Rachel’s conversation involved her partner. Test whether clarifying who should attend improves expectations and preparation.</p><h3>What needs review</h3><p>Agency-approved wording, target audience, channel eligibility, required disclosures and the actual landing-page experience.</p><button class="primary wide" data-feature="record-creative-review">Record a demo review request</button><p class="footnote">One conversation is a hypothesis source, not validated market insight.</p>`,'CONVERSATION FEEDBACK');break;case 'record-creative-review':state.creativeReview=true;closeDrawer();toast('Sample message queued for agency review. No campaign changed.');break;case 'funnel-view':state.marketingTab='funnels';navigate('marketing');break;case 'simulate-lead':drawer('An inquiry arrives with context',`<span class="badge green">Simulation only</span><div class="inset"><strong>Rachel Bennett</strong><br>Source: Paid social<br>Campaign: Family protection conversations<br>Preference: Email, then a scheduled call<br>Owner: Morgan Reed</div><p>The source and contact preference travel with the record, so the producer starts with context.</p><button class="primary wide" data-action="morgan-conversation">Follow the inquiry into a conversation →</button>`,'LEAD CAPTURE');break;case 'automation':drawer('Approved follow-through workflow',`<span class="badge">Workflow preview · Not running</span><div class="workflow-vertical">${[['Trigger','An inquiry is captured with source and preferences.'],['Assign','Apply approved routing and create a producer task.'],['Prepare','Draft an acknowledgment using approved content.'],['Pause on reply','Stop scheduled nurture and alert the producer.'],['Verify','Check activity and surface missing follow-through.']].map(([k,v],i)=>`<div class="task"><span class="section-number">${i+1}</span><div><h3>${k}</h3><p>${v}</p></div></div>`).join('')}</div><button class="primary wide" style="margin-top:20px" data-action="morgan-conversation">Inspect a conversation-aware action →</button>`,'GROWTH & FOLLOW-THROUGH');break;case 'prep':drawer('Prepare for Rachel’s call',`<span class="badge">Producer preparation · Fictional example</span><div class="detailrow"><span>Source</span><strong>Paid social</strong></div><div class="detailrow"><span>Current context</span><strong>Partner involved</strong></div><div class="detailrow"><span>Customer request</span><strong>Email summary, then Thursday call</strong></div><div class="inset"><strong>Preparation prompts</strong><br>Review the last conversation.<br>Check what was promised and what was sent.<br>Confirm whether the partner will join.<br>Use approved guidance; escalate insurance questions.</div><button class="primary wide" data-action="morgan-conversation">Read the conversation →</button>`,'BEFORE THE CONVERSATION');break;case 'recruiting-fit':drawer('People decisions stay with people',`<p>This workspace coordinates candidate communications, interviews and onboarding tasks.</p><div class="inset">Agency leaders retain candidate selection, licensing checks, appointments, readiness and permissions. No automated hiring or insurance-authorization decision is shown.</div>`);break;case 'status-source':drawer('Coordination is not the source record',`<div class="inset"><strong>This product:</strong> Who needs to do what next?<br><br><strong>AMS / carrier / authorized source:</strong> What is the verified policy or case status?</div><p>The platform should show source timestamps and missing information. A completed follow-up task never establishes that coverage is in force.</p>`);break;case 'persistency':drawer('Persistency view: required inputs',`<p>A future view would group policies by a defined inception cohort and follow their verified in-force status over time.</p>${['Policy and cohort identifiers','Inception and observation dates','Verified in-force / lapse status','Carrier or AMS source and freshness','Service exceptions and assigned owner'].map(t=>`<div class="detailrow">${t}</div>`).join('')}<div class="inset">Current demo state: source data not connected. Persistency percentage unavailable.</div><p>Timely service can support retention; a particular retention improvement is not promised.</p>`);break;case 'referral':drawer('A relevant referral invitation',`<span class="badge orange">Agency-approved message required</span><div class="inset">“Thank you for giving us the opportunity to help. If someone you know would find a conversation useful, you’re welcome to introduce us.”</div><p>Prepare the invitation after the service issue has been resolved, respect preferences, and have the agency review the context and wording.</p><button class="primary wide" data-feature="record-referral">Save sample invitation for review</button>`);break;case 'record-referral':closeDrawer();toast('Sample invitation saved for review. No message sent.');break;case 'individual-record':drawer('Jamie Ellis · Personal record',`<span class="badge">Jordan Taylor’s independent workspace</span><p>Jamie asked to review the information with a partner before scheduling the next conversation.</p><div class="inset"><strong>Next step:</strong> Prepare an approved summary and propose a specific time.<br><strong>Owner:</strong> Jordan Taylor<br><strong>Data source:</strong> Separate fictional individual dataset</div><p>This example belongs to the independent subscriber. It is not a Northstar agency record.</p>`);break;case 'individual-training':drawer('Jordan’s personal learning plan',`<h3>Current focus: a clear next step</h3><div class="inset">Learn: action, date, time, channel and attendees.<br>Practise: respond to a partner-involved decision.<br>Apply: use it in the next customer conversation.<br>Review: compare the later record with the agreed standard.</div><p>Practice completion and behavior change are separate measures.</p>`);break;default:toast('This concept is represented in the current workspace.')}}
function knowledgeAnswer(k){const text={followup:'Record the promised action, responsible producer, date, time, channel and completion evidence. If the customer said “Thursday afternoon,” confirm a specific time.<br><br><strong>Source:</strong> Sample Follow-through playbook, §2.1 · Approved Sep 1, 2026.',handoff:'Include customer context, the agreed next step, required or missing information, the receiving owner and the source timestamp. Verify case status in the authorized record.<br><br><strong>Source:</strong> Sample Application handoff checklist, §1.3 · Approved Aug 28, 2026.',coverage:'This question requires insurance judgment. The sample playbooks do not establish an appropriate coverage recommendation. Route it to the authorized insurance professional with the customer’s context.<br><br><strong>Source:</strong> Sample Escalation guide, §1.0 · Approved Sep 1, 2026.'}[k];const target=document.getElementById('knowledge-answer');if(target)target.innerHTML=`<div class="answer">${text}</div>`;else drawer('Approved-source answer',`<div class="answer">${text}</div>`)}
function caseDrawer(n){if(n==='Rachel Bennett'){state.selected=n;navigate('conversations');return;}drawer(n+' · Handoff',`<span class="badge orange">Coordination example · Source confirmation required</span><div class="inset"><strong>Customer context:</strong> The customer has agreed to continue the application process.<br><strong>Current dependency:</strong> ${n==='Daniel Foster'?'Requested information is outstanding.':'The receiving owner needs a complete handoff.'}<br><strong>Next owner:</strong> ${n==='Daniel Foster'?'Lena Brooks':'Alex Carter'}</div>${['Customer’s stated request preserved','Agreed next step recorded','Missing information identified','Receiving owner assigned','Authoritative case status checked'].map((v,i)=>`<label class="readiness-row"><input type="checkbox" ${i<3?'checked':''}>${v}</label>`).join('')}<button class="primary wide" style="margin-top:20px" data-feature="record-handoff">Save demo checklist</button><p class="footnote">No application is submitted and no policy record is changed.</p>`,'CASE COORDINATION');const b=document.querySelector('[data-feature="record-handoff"]');if(b)b.onclick=()=>{state.handoffSaved=true;closeDrawer();toast('Sample handoff checklist reviewed. No source system changed.')}}
function rolloutDrawer(n){const data={1:['Agency profile','Choose a supported agency workflow and enter the identity used across the shared product.'],2:['Supported connections','Choose the records needed for the agency workflow and confirm who may view or update them. Verify supported connections with the agency.'],3:['People and roles','Assign owner, manager and producer visibility. Financial permissions must apply to records, reports, exports and AI answers.'],4:['Approved knowledge','Use standard fields for playbook title, owner, version, approval date and escalation instructions.'],5:['Financial definitions','Keep premium volume, earned commissions, cash receipts, chargebacks, direct costs and overhead distinct.'],6:['Readiness checks','Check source completeness, access boundaries, approved content, workflow stop conditions and recovery procedures.']}[n];drawer(data[0],`<span class="badge">Standard onboarding concept · Step ${n} of 6</span><p>${data[1]}</p><div class="inset">Same product and onboarding structure for every supported customer. Agency settings and approved records are inputs, not a separate software build.</div>${n==='2'?'<p class="footnote">No authentication, credentials or live connections are requested by this demo.</p>':''}<button class="primary wide" data-rollout-next="${Number(n)+1}">${n==='6'?'Return to rollout overview':'Preview next step'} →</button>`,'SHARED SAAS PRODUCT');document.querySelector('[data-rollout-next]').onclick=()=>Number(n)<6?rolloutDrawer(String(Number(n)+1)):closeDrawer()}
function richerBindings(root=document){root.querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>feature(b.dataset.feature));root.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>marketingChannel(b.dataset.channel));root.querySelectorAll('[data-journey]').forEach(b=>b.onclick=()=>({campaign:()=>feature('campaign-builder'),lead:()=>contactDrawer('Rachel Bennett'),conversation:()=>action('morgan-conversation'),followup:()=>navigate('actions')}[b.dataset.journey])());root.querySelectorAll('[data-marketingtab]').forEach(b=>b.onclick=()=>{state.marketingTab=b.dataset.marketingtab;render()});root.querySelectorAll('[data-trainingtab]').forEach(b=>b.onclick=()=>{state.trainingTab=b.dataset.trainingtab;render()});root.querySelectorAll('[data-caretab]').forEach(b=>b.onclick=()=>{state.careTab=b.dataset.caretab;render()});root.querySelectorAll('[data-platformtab]').forEach(b=>b.onclick=()=>{state.platformTab=b.dataset.platformtab;render()});root.querySelectorAll('[data-funnel]').forEach(b=>b.onclick=()=>feature(b.dataset.funnel==='Capture'?'simulate-lead':'automation'));root.querySelectorAll('[data-performance]').forEach(b=>b.onclick=()=>{const p=people.find(p=>p.name===b.dataset.performance);drawer(p.name+' · Activity',`<div class="namecell">${avatar(p)}<h3>${p.role}</h3></div><div class="inset"><strong>${p.leads} leads → ${p.placed} placements</strong><br>${(p.placed/p.leads*100).toFixed(1)}% conversion in the August sample</div><p>Inspect the source conversation, check commitments and choose the appropriate coaching or process response.</p><div class="stack"><button class="primary" data-action="morgan-conversation">Explore the Rachel / Morgan example</button><button data-feature="producer-onboarding">View development foundation</button>${isOwn()?`<button data-person="${p.name}">Inspect contribution after costs</button>`:''}</div>`,'PRODUCER ACTIVITY')});root.querySelectorAll('[data-producer-training]').forEach(b=>b.onclick=()=>{state.trainingTab='paths';navigate('coaching');toast('Illustrative learning paths. The active scenario follows Morgan.')});root.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>trainingPath(b.dataset.track));root.querySelectorAll('[data-onboard]').forEach(b=>b.onclick=()=>{const n=b.dataset.onboard;drawer('Readiness checkpoint '+n,`<p>Review the required evidence with the producer and the responsible manager.</p><div class="inset">${n==='5'?'Readiness is not yet approved. The authorized agency leader retains the decision.':'Completion in this demo does not grant licensing, appointments, production access or authority to sell.'}</div><button class="primary wide" data-action="${n==='3'?'practice':n==='4'?'coach-review':'lesson'}">${n==='3'?'Open practice':n==='4'?'Open review criteria':'Open sample guidance'}</button>`)});root.querySelectorAll('[data-knowledge]').forEach(b=>b.onclick=()=>knowledgeAnswer(b.dataset.knowledge));root.querySelectorAll('[data-recruit]').forEach(b=>b.onclick=()=>drawer(b.dataset.recruit,`<span class="badge">Fictional coordination record</span><div class="inset">Responsible manager: Jordan Lee<br>Next step: Confirm the meeting or onboarding checklist.<br>Decision status: Reserved for the agency leader.</div><button class="primary wide" data-feature="producer-onboarding">Preview onboarding support →</button><p class="footnote">No hiring recommendation, suitability assessment or licensing decision is generated.</p>`,'RECRUITING COORDINATION'));root.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>caseDrawer(b.dataset.case));root.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>drawer(b.dataset.service+' · Service',`<p>A customer-facing question or review is waiting for an assigned agency team member.</p><div class="inset"><strong>Next action:</strong> Review the request, confirm any relevant source information and respond through the approved channel.<br><strong>Completion:</strong> Verify the customer received the response.</div><button class="primary wide" data-feature="referral">Preview a later referral invitation</button><p class="footnote">Resolve the service issue before considering a referral request.</p>`));root.querySelectorAll('[data-journey-stage]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.journeyStage);if(n===1)navigate('marketing');else if(n===2)navigate('contacts');else if(n===3)drawer('Insurance advice remains with the licensed team','<p>The platform prepares context and coordinates next steps. Authorized professionals retain advice, quoting, coverage and other insurance decisions.</p>');else{state.careTab=n===6?'care':'handoffs';navigate('coordination')}});root.querySelectorAll('[data-rollout]').forEach(b=>b.onclick=()=>rolloutDrawer(b.dataset.rollout));root.querySelectorAll('[data-preview-role]').forEach(b=>b.onclick=()=>{state.role=b.dataset.previewRole;state.tour=-1;navigate('dashboard')});root.querySelectorAll('[data-coverage]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.coverage);if([1,12,13,14].includes(i)){state.platformTab={1:'partner',12:'fit',13:'rollout',14:'editions'}[i];navigate('platform')}else {if(i===9)state.marketingTab='feedback';navigate(coverage[i][2])}});root.querySelectorAll('[data-agentstage]').forEach(b=>b.onclick=()=>drawer(b.dataset.agentstage+' the work',`<p>${{Observe:'Read only permitted conversations and activity, preserving source dates.',Interpret:'Separate customer statements from proposed actions and unresolved uncertainty.',Coordinate:'Prepare the next step, assign an owner and request approval.',Verify:'Look for recorded completion. Missing activity is a reason to check, not proof of inaction.'}[b.dataset.agentstage]}</p><button class="primary wide" data-action="morgan-conversation">Explore the complete example →</button>`))}
drawer=function(title,html,label='GROWTH & PERFORMANCE'){oldDrawer(title,html,label);richerBindings(document.getElementById('overlay'))};
bind=function(){oldBind();richerBindings();document.getElementById('role').onchange=e=>{state.role=e.target.value;state.tour=-1;state.page='dashboard';closeDrawer();render()}};
const extendedTour=[['dashboard','owner','The connected growth story','Start with acquisition, producer execution, ongoing development and the business result.'],['marketing','owner','Every channel belongs in the picture','Explore channels, campaigns, funnels and how conversations inform marketing.'],['producers','owner','Measure the work behind the result','Open a producer’s activity and connect the numbers to a specific coaching need.'],['conversations','owner','Inspect the evidence','Rachel’s request generates both a follow-up plan and a development opportunity. Approve the plan to try it.'],['coaching','owner','Make training continuous','Explore learning paths, practise the scenario and inspect the manager’s review.'],['coordination','owner','Carry the customer forward','Explore application handoffs, the customer journey and ongoing service.'],['profitability','owner','Connect the outcome to the costs','Inspect agency results, producer contribution and marketing return.'],['platform','owner','See the distinction and the scalable product','Explore AMS fit, editions, permissions, standard rollout and the partnership.']];
tourHTML=function(){if(state.tour<0)return '';const s=extendedTour[state.tour];return `<div class="tour"><span class="tour-count">${state.tour+1} / ${extendedTour.length}</span><div><strong>${s[2]}</strong><p>${s[3]}</p></div><div class="actions"><button class="ghost small" data-action="exit-tour">Exit</button>${state.tour>0?'<button class="small" data-action="tour-back">Back</button>':''}<button class="primary small" data-action="tour-next">${state.tour===extendedTour.length-1?'Finish':'Next'} ${ic('arrow')}</button></div></div>`};
action=function(a){if(a==='close'){closeDrawer();render();return}if(a==='tour'){state.tour=0;state.role='owner';navigate('dashboard');return}if(a==='tour-next'||a==='tour-back'){state.tour+=a==='tour-next'?1:-1;if(state.tour>=extendedTour.length){state.tour=-1;navigate('dashboard');toast('Concept walkthrough complete. Explore any workspace.')}else{state.role='owner';navigate(extendedTour[state.tour][0])}return}if(a==='workspace'){drawer('Your agency workspace','<p>Northstar Insurance is a fictional agency used to demonstrate the growth and producer-performance concept.</p><div class="inset">Connected agency workspace<br>Shared software, agency-specific settings<br>Separate customer data and role boundaries</div><button class="primary wide" data-page="platform">Understand the product and AMS distinction →</button>');return}if(a==='about'){state.platformTab='fit';navigate('platform');return}if(a==='ask'&&state.role==='individual'){drawer('Your personal assistant','<p>This edition would answer from your own records and approved guidance.</p><div class="answer">Jordan’s sample business has 24 inquiries, 6 placements, $7,200 net revenue and $1,400 direct marketing/software costs. These are a separate fictional dataset, not Northstar’s records.</div>');return}if(a==='ask'&&state.role==='manager'){drawer('Your team assistant','<span class="badge">Scripted manager answer</span><div class="answer">Review Rachel’s outstanding follow-up with Morgan, verify Alex’s callback activity and check the week’s coaching focus. Financial access has not been granted to this manager role.</div><button class="primary wide" style="margin-top:20px" data-page="actions">Open team actions →</button>');return}oldAction(a)};
render();
